"use client";

import "./pagination.css";
import { ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/cn";

import { PaginationContext, usePaginationContext } from "./pagination.context";
import { paginationVariants, type PaginationVariants } from "./pagination.variants";

export type PaginationProps = PaginationVariants & React.ComponentProps<"nav">;

export const PaginationRoot = ({ children, className, size, ...props }: PaginationProps) => {
  const slots = paginationVariants({ size });

  return (
    <PaginationContext.Provider value={{ slots }}>
      <nav
        aria-label="pagination"
        className={cn(slots.root(), className)}
        {...props}
      >
        {children}
      </nav>
    </PaginationContext.Provider>
  );
};

export type PaginationContentProps = React.ComponentProps<"ul">;

export const PaginationContent = ({ className, ...props }: PaginationContentProps) => {
  const { slots } = usePaginationContext();
  return <ul className={cn(slots.content(), className)} {...props} />;
};

export type PaginationItemProps = React.ComponentProps<"li">;

export const PaginationItem = ({ className, ...props }: PaginationItemProps) => {
  const { slots } = usePaginationContext();
  return <li className={cn(slots.item(), className)} {...props} />;
};

export type PaginationLinkProps = {
  isActive?: boolean;
} & React.ComponentProps<"a">;

export const PaginationLink = ({
  className,
  isActive,
  "aria-current": ariaCurrent,
  ...props
}: PaginationLinkProps) => {
  const { slots } = usePaginationContext();
  return (
    <a
      aria-current={isActive ? (ariaCurrent ?? "page") : undefined}
      className={cn(
        slots.link(),
        isActive && "pagination__link--active",
        className
      )}
      {...props}
    />
  );
};

export type PaginationPreviousProps = React.ComponentProps<typeof PaginationLink>;

export const PaginationPrevious = ({
  className,
  children,
  ...props
}: PaginationPreviousProps) => (
  <PaginationLink
    aria-label="Go to previous page"
    className={cn("gap-1 pl-2.5", className)}
    {...props}
  >
    {children ?? (
      <>
        <ChevronLeft className="h-4 w-4" />
        <span>Previous</span>
      </>
    )}
  </PaginationLink>
);

export type PaginationNextProps = React.ComponentProps<typeof PaginationLink>;

export const PaginationNext = ({
  className,
  children,
  ...props
}: PaginationNextProps) => (
  <PaginationLink
    aria-label="Go to next page"
    className={cn("gap-1 pr-2.5", className)}
    {...props}
  >
    {children ?? (
      <>
        <span>Next</span>
        <ChevronRight className="h-4 w-4" />
      </>
    )}
  </PaginationLink>
);

export type PaginationEllipsisProps = React.ComponentProps<"span">;

export const PaginationEllipsis = ({
  className,
  children,
  ...props
}: PaginationEllipsisProps) => {
  const { slots } = usePaginationContext();
  return (
    <span
      aria-hidden="true"
      className={cn(slots.ellipsis(), className)}
      {...props}
    >
      {children ?? <MoreHorizontal className="h-4 w-4" />}
      <span className="sr-only">More pages</span>
    </span>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const paginationVariants = tv({
  slots: {
    root: "pagination",
    content: "pagination__content",
    item: "pagination__item",
    link: "pagination__link",
    ellipsis: "pagination__ellipsis",
  },
  variants: {
    size: {
      sm: {
        link: "pagination__link--sm",
        ellipsis: "h-8 w-8 text-xs",
      },
      md: {
        link: "pagination__link--md",
        ellipsis: "h-9 w-9 text-sm",
      },
      lg: {
        link: "pagination__link--lg",
        ellipsis: "h-10 w-10 text-base",
      },
    },
    isActive: {
      true: {
        link: "pagination__link--active",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type PaginationVariants = VariantProps<typeof paginationVariants>;

"use client";

import { createContext, useContext } from "react";

import { paginationVariants } from "./pagination.variants";

export type PaginationContext = {
  slots: ReturnType<typeof paginationVariants>;
};

export const PaginationContext = createContext<PaginationContext | null>(null);

export const usePaginationContext = () => {
  const context = useContext(PaginationContext);
  return context ?? { slots: paginationVariants() };
};

.pagination {
  @apply mx-auto flex w-full justify-center;
}

.pagination__content {
  @apply flex flex-row items-center gap-1;
}

.pagination__item {
  @apply list-none;
}

.pagination__link {
  @apply focus-visible:outline-ring hover:bg-accent hover:text-accent-foreground text-foreground inline-flex items-center justify-center gap-1.5 rounded-md text-sm font-medium transition-colors focus-visible:outline-2 disabled:pointer-events-none disabled:opacity-50 select-none cursor-pointer;
}

.pagination__link--active {
  @apply border-input bg-background shadow-xs hover:bg-accent border;
}

.pagination__link--sm {
  @apply h-8 min-w-8 px-2 text-xs;
}

.pagination__link--md {
  @apply h-9 min-w-9 px-3 text-sm;
}

.pagination__link--lg {
  @apply h-10 min-w-10 px-4 text-base;
}

.pagination__ellipsis {
  @apply text-muted-foreground flex h-9 w-9 items-center justify-center;
}

import {
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
  PaginationRoot,
} from "./pagination";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/pagination/content.md
 */
export const Pagination = {
  Content: PaginationContent,
  Ellipsis: PaginationEllipsis,
  Item: PaginationItem,
  Link: PaginationLink,
  Next: PaginationNext,
  Previous: PaginationPrevious,
  Root: PaginationRoot,
};

export {
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
  PaginationRoot,
};

export type {
  PaginationContentProps,
  PaginationEllipsisProps,
  PaginationItemProps,
  PaginationLinkProps,
  PaginationNextProps,
  PaginationPreviousProps,
  PaginationProps,
} from "./pagination";
export { PaginationContext, usePaginationContext } from "./pagination.context";
export { type PaginationVariants, paginationVariants } from "./pagination.variants";
